package com.shopsphere;import java.time.Instant;import java.util.UUID;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class InventoryService{private final InventoryRepository repo;public InventoryService(InventoryRepository r){repo=r;}public Inventory get(UUID id){return repo.find(id).orElseThrow(()->new NotFoundException("Inventory not found"));}public Inventory set(UUID productId,String sku,int quantity,int reorder){if(quantity<0||reorder<0)throw new BusinessException("Stock values cannot be negative");Inventory old=repo.find(productId).orElse(new Inventory(UUID.randomUUID(),productId,sku,0,0,reorder,Instant.now()));if(quantity<old.quantityReserved())throw new BusinessException("Stock cannot be lower than reserved quantity");return repo.save(new Inventory(old.id(),productId,sku,quantity,old.quantityReserved(),reorder,Instant.now()));}public Inventory reserve(UUID id,int quantity){if(quantity<=0)throw new BusinessException("Reservation quantity must be positive");Inventory i=get(id);if(i.sellable()<quantity)throw new BusinessException("Insufficient available stock");return repo.save(new Inventory(i.id(),i.productId(),i.sku(),i.quantityAvailable(),i.quantityReserved()+quantity,i.reorderLevel(),Instant.now()));}public Inventory release(UUID id,int quantity){if(quantity<=0)throw new BusinessException("Release quantity must be positive");Inventory i=get(id);if(quantity>i.quantityReserved())throw new BusinessException("Cannot release more than reserved quantity");return repo.save(new Inventory(i.id(),i.productId(),i.sku(),i.quantityAvailable(),i.quantityReserved()-quantity,i.reorderLevel(),Instant.now()));}}
